import{_ as t,o,c as e,a4 as s}from"./chunks/framework.vNSRaLQv.js";const h=JSON.parse('{"title":"海思 HI3798MV100 盒子刷机记录","description":"","frontmatter":{"title":"海思 HI3798MV100 盒子刷机记录","date":"2026-07-19T00:00:00.000Z"},"headers":[],"relativePath":"posts/盒子刷机记录.md","filePath":"posts/盒子刷机记录.md"}'),d={name:"posts/盒子刷机记录.md"};function r(n,a,l,i,c,p){return o(),e("div",null,[...a[0]||(a[0]=[s(`<h1 id="海思-hi3798mv100-盒子刷机记录" tabindex="-1">海思 HI3798MV100 盒子刷机记录 <a class="header-anchor" href="#海思-hi3798mv100-盒子刷机记录" aria-label="Permalink to &quot;海思 HI3798MV100 盒子刷机记录&quot;">​</a></h1><h2 id="新分区表-去-logo、recovery、backup" tabindex="-1">新分区表（去 logo、recovery、backup） <a class="header-anchor" href="#新分区表-去-logo、recovery、backup" aria-label="Permalink to &quot;新分区表（去 logo、recovery、backup）&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>fastboot   0M    1M    ← 不动</span></span>
<span class="line"><span>bootargs   1M    1M    ← 不动</span></span>
<span class="line"><span>baseparam  2M    4M    ← 不动</span></span>
<span class="line"><span>pqparam    6M    4M    ← 不动</span></span>
<span class="line"><span>kernel    10M   20M    ← 原来 14M，前移 4M</span></span>
<span class="line"><span>rootfs    30M    -     ← 原来 610M，现在从 30M 开始，约 7.1G</span></span></code></pre></div><p>XML 文件: <code>/home/a1/下载/emmc_TTL-hi3798mv100-32-new.xml</code></p><h2 id="刷机后必须改-bootargs" tabindex="-1">刷机后必须改 bootargs <a class="header-anchor" href="#刷机后必须改-bootargs" aria-label="Permalink to &quot;刷机后必须改 bootargs&quot;">​</a></h2><p>刷完后串口进 fastboot，改 bootargs：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>setenv bootargs model=mv100 console=ttyAMA0,115200 root=/dev/mmcblk0p6 rootfstype=ext4 rootwait blkdevparts=mmcblk0:1M(boot),1M(bootargs),4M(baseparam),4M(pqparam),20M(kernel),-(rootfs)</span></span>
<span class="line"><span>saveenv</span></span>
<span class="line"><span>run bootcmd</span></span></code></pre></div><p><strong>关键变化：</strong></p><ul><li><code>root=/dev/mmcblk0p9</code> → <code>root=/dev/mmcblk0p6</code>（分区号变了）</li><li><code>blkdevparts</code> 删掉了 logo、busybox、backup</li></ul><h2 id="usb-盘备份文件" tabindex="-1">USB 盘备份文件 <a class="header-anchor" href="#usb-盘备份文件" aria-label="Permalink to &quot;USB 盘备份文件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文件</th><th>大小</th><th>用途</th></tr></thead><tbody><tr><td><code>rootfs.img</code></td><td>900MB</td><td>dd 镜像，可刷分区</td></tr><tr><td><code>kernel.img</code></td><td>20MB</td><td>内核备份</td></tr><tr><td><code>rootfs.tar.gz</code></td><td>259MB</td><td>tar 备份</td></tr></tbody></table><h2 id="nfs-网络共享" tabindex="-1">NFS 网络共享 <a class="header-anchor" href="#nfs-网络共享" aria-label="Permalink to &quot;NFS 网络共享&quot;">​</a></h2><ul><li>盒子: <code>/dev/sda</code> → <code>/mnt/shared</code>，NFS 导出</li><li>主机: <code>192.168.31.82:/mnt/shared</code> → <code>/mnt/nas</code>（NFSv3）</li><li>开机自动挂载（双方 fstab 都配了）</li></ul><h2 id="刷机流程" tabindex="-1">刷机流程 <a class="header-anchor" href="#刷机流程" aria-label="Permalink to &quot;刷机流程&quot;">​</a></h2><ol><li>USB 盘插主机，进 VM</li><li>HiTool 加载新 XML 分区表</li><li>选择 rootfs.img 刷 rootfs 分区（30M 起始）</li><li>串口进 fastboot 改 bootargs</li><li><code>run bootcmd</code> 启动测试</li></ol><h2 id="⚠️-注意事项" tabindex="-1">⚠️ 注意事项 <a class="header-anchor" href="#⚠️-注意事项" aria-label="Permalink to &quot;⚠️ 注意事项&quot;">​</a></h2><h3 id="bootargs9-32-bin-是旧的" tabindex="-1">bootargs9-32.bin 是旧的 <a class="header-anchor" href="#bootargs9-32-bin-是旧的" aria-label="Permalink to &quot;bootargs9-32.bin 是旧的&quot;">​</a></h3><p>HiTool 刷机时会刷 bootargs 分区，用的是原始 <code>bootargs9-32.bin</code>，里面还是旧配置。<strong>必须串口改。</strong></p><h3 id="分区号变化" tabindex="-1">分区号变化 <a class="header-anchor" href="#分区号变化" aria-label="Permalink to &quot;分区号变化&quot;">​</a></h3><table tabindex="0"><thead><tr><th>分区</th><th>旧版</th><th>新版</th></tr></thead><tbody><tr><td>rootfs</td><td>mmcblk0p9</td><td>mmcblk0p6</td></tr><tr><td>logo</td><td>mmcblk0p5</td><td>已删除</td></tr><tr><td>recovery</td><td>mmcblk0p7</td><td>已删除</td></tr><tr><td>backup</td><td>mmcblk0p8</td><td>已删除</td></tr></tbody></table><h3 id="u-boot-网络" tabindex="-1">U-Boot 网络 <a class="header-anchor" href="#u-boot-网络" aria-label="Permalink to &quot;U-Boot 网络&quot;">​</a></h3><p>U-Boot 里 IP 是 <code>192.168.1.10</code>，主机是 <code>192.168.31.x</code>，TFTP 不能直接用。要改 U-Boot 网络配对。</p><h3 id="翻车修复" tabindex="-1">翻车修复 <a class="header-anchor" href="#翻车修复" aria-label="Permalink to &quot;翻车修复&quot;">​</a></h3><p>如果刷完起不来，串口改回旧 bootargs：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>setenv bootargs model=mv100 console=ttyAMA0,115200 root=/dev/mmcblk0p9 rootfstype=ext4 rootwait blkdevparts=mmcblk0:1M(boot),1M(bootargs),4M(baseparam),4M(pqparam),4M(logo),20M(kernel),64M(busybox),512M(backup),-(ubuntu)</span></span>
<span class="line"><span>saveenv</span></span>
<span class="line"><span>run bootcmd</span></span></code></pre></div><h2 id="主机桌面崩溃教训" tabindex="-1">主机桌面崩溃教训 <a class="header-anchor" href="#主机桌面崩溃教训" aria-label="Permalink to &quot;主机桌面崩溃教训&quot;">​</a></h2><p><strong>问题：</strong> 重启 sddm 导致桌面无限密码认证循环</p><p><strong>原因：</strong> sddm 重启时，NFS 挂载点（/mnt/nas）可能卡住，影响 sddm 启动</p><p><strong>解决：</strong></p><ol><li>弹出 VM 里所有 USB 设备</li><li><code>sudo umount -l /mnt/nas</code></li><li><code>sudo reboot</code></li></ol><p><strong>教训：</strong> 重启 sddm 前先卸载 NFS 挂载点</p>`,31)])])}const m=t(d,[["render",r]]);export{h as __pageData,m as default};
